868	/// Block swizzling function for streamk Gemms
869	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
870	struct StreamkGemmIdentityBlockSwizzle {
871	    /// Data members
872	
873	    GemmCoord problemShape;
874	    GemmCoord tileMNK;
875	    GemmCoord loopsMNK;
876	    uint32_t blockDim;
877	    // Represents the number of ordinary blocks.
878	    uint32_t normalBlocks;
879	    // Represents the number of blocks that need to be split according to the Streamk algorithm.
880	    uint32_t streamkBlocks;
881	    // If computing streamk blocks, how many kTile should each core process
882	    uint32_t kTileNumPerCore;
883	    // Since the number of kTiles may not be evenly divisible by the number of cores,
884	    // some cores need to compute one additoinal kTile compared to others
885	    uint32_t kTileRemain;
886	
887	    struct StreamkBlockDec {
888	        // If the current block is a ordinary block, set it to false.
889	        // If it is a streamk block, set it to true.
890	        bool isStreamkBlock{false};
891	        // If the current block is a cross block-meaning it consists partly of the tail k portion of the
892	        // current basic block and partly of the head k portion of the next basic block, set it to true.
893	        bool isCrossBlock{false};
894	
895	        GemmCoord blockCoord;
896	        GemmCoord actualBlockShape;
897	        GemmCoord streamkBlockCoord;
898	        GemmCoord streamkActualBlockShape;
899	    };
900	
901	    /// Methods
902	
903	    CATLASS_DEVICE
904	    StreamkGemmIdentityBlockSwizzle()
905	    {}
906	
907	    CATLASS_DEVICE
908	    StreamkGemmIdentityBlockSwizzle(GemmCoord const& problemShape_, GemmCoord const& tileMNK_, uint32_t blockDim_)
909	        : problemShape(problemShape_), tileMNK(tileMNK_), blockDim(blockDim_)
910	    {
911	        loopsMNK = CeilDiv(problemShape, tileMNK);
912	        streamkBlocks = loopsMNK.m() * loopsMNK.n() % blockDim;
913	        normalBlocks = loopsMNK.m() * loopsMNK.n() - streamkBlocks;
914	        kTileNumPerCore = streamkBlocks * loopsMNK.k() / blockDim;
915	        kTileRemain = streamkBlocks * loopsMNK.k() % blockDim;
916	    }
917	
918	    CATLASS_DEVICE
919	    uint32_t GetCoreLoops() const
920	    {
921	        uint32_t blocksNum = loopsMNK.m() * loopsMNK.n();
922	        uint32_t coreLoops = blocksNum / blockDim * blockDim + min(streamkBlocks * loopsMNK.k(), blockDim);
923	        return coreLoops;
924	    }
925	
926	    CATLASS_DEVICE
927	    GemmCoord GetBlockCoord(uint32_t taskIdx)
928	    {
929	        uint32_t innerIdx = taskIdx % GetCoreLoops();
930	        if constexpr (SwizzleDirection == 0) { // Zn
931	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), SwizzleOffset);
932	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.n());
933	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.n());
934	
935	            uint32_t nRow = SwizzleOffset;
936	            if (tileBlockIdx == tileBlockLoop - 1) {
937	                nRow = loopsMNK.m() - SwizzleOffset * tileBlockIdx;
938	            }
939	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
940	            uint32_t nIdx = inTileBlockIdx / nRow;
941	            if (tileBlockIdx % 2 == 1) {
942	                nIdx = loopsMNK.n() - nIdx - 1;
943	            }
944	            return GemmCoord{mIdx, nIdx, 0};
945	        } else if constexpr (SwizzleDirection == 1) { // Nz
946	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), SwizzleOffset);
947	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.m());
948	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.m());
949	
950	            uint32_t nCol = SwizzleOffset;
951	            if (tileBlockIdx == tileBlockLoop - 1) {
952	                nCol = loopsMNK.n() - SwizzleOffset * tileBlockIdx;
953	            }
954	            uint32_t mIdx = inTileBlockIdx / nCol;
955	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
956	            if (tileBlockIdx % 2 == 1) {
957	                mIdx = loopsMNK.m() - mIdx - 1;
958	            }
959	            return GemmCoord{mIdx, nIdx, 0};
960	        }
961	    }
962	
963	    CATLASS_DEVICE
964	    GemmCoord GetActualBlockShape(GemmCoord blockCoord)
965	    {
966	        uint32_t mActual =
967	            (blockCoord.m() == (loopsMNK.m() - 1)) ? (problemShape.m() - blockCoord.m() * tileMNK.m()) : tileMNK.m();
968	        uint32_t nActual =
969	            (blockCoord.n() == (loopsMNK.n() - 1)) ? (problemShape.n() - blockCoord.n() * tileMNK.n()) : tileMNK.n();
970	        uint32_t kActual = problemShape.k();
971	        return GemmCoord{mActual, nActual, kActual};
972	    }
973	
974	    CATLASS_DEVICE
975	    uint32_t GetStreamkBlockNum()
976	    {
977	        return streamkBlocks;
978	    }
979	
980	    CATLASS_DEVICE
981	    uint32_t GetNormalBlockNum()
982	    {
983	        return normalBlocks;
984	    }
985	
986	    CATLASS_DEVICE
987	    void GetStreamkBlockDec(uint32_t loopIdx, StreamkBlockDec& streamkBlockDec)
988	    {
989	        if (loopIdx < normalBlocks) {
990	            streamkBlockDec.isStreamkBlock = false;
991	            streamkBlockDec.isCrossBlock = false;
992	            streamkBlockDec.blockCoord = GetBlockCoord(loopIdx);
993	            streamkBlockDec.actualBlockShape = GetActualBlockShape(streamkBlockDec.blockCoord);
994	        } else {
995	            streamkBlockDec.isStreamkBlock = true;
996	            uint32_t curKTileNum = kTileNumPerCore;
997	            uint32_t kTileIdx = ((loopIdx - normalBlocks) * kTileNumPerCore + kTileRemain);
998	            if (loopIdx - normalBlocks < kTileRemain) {
999	                curKTileNum += 1;
1000	                kTileIdx = ((loopIdx - normalBlocks) * curKTileNum);
1001	            }
1002	            uint32_t streamkBlockIdx = kTileIdx / loopsMNK.k();
1003	            GemmCoord blockCoordTmp = GetBlockCoord(normalBlocks + streamkBlockIdx);
1004	            streamkBlockDec.blockCoord = GemmCoord{blockCoordTmp.m(), blockCoordTmp.n(), kTileIdx % loopsMNK.k()};
1005	
1006	            uint32_t nextStreamkBlockIdx = (kTileIdx + curKTileNum) / loopsMNK.k();
1007	            streamkBlockDec.isCrossBlock = false;
1008	            GemmCoord actualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.blockCoord);
1009	            if ((kTileIdx % loopsMNK.k() + curKTileNum) * tileMNK.k() > problemShape.k()) {
1010	                streamkBlockDec.actualBlockShape = GemmCoord{
1011	                    actualBlockShapeTmp.m(), actualBlockShapeTmp.n(),
1012	                    problemShape.k() - (kTileIdx % loopsMNK.k()) * tileMNK.k()};
1013	            } else {
1014	                streamkBlockDec.actualBlockShape =
1015	                    GemmCoord{actualBlockShapeTmp.m(), actualBlockShapeTmp.n(), curKTileNum * tileMNK.k()};
1016	            }
1017	            if (kTileIdx % loopsMNK.k() + curKTileNum > loopsMNK.k()) {
1018	                streamkBlockDec.isCrossBlock = true;
1019	                streamkBlockDec.streamkBlockCoord = GetBlockCoord(normalBlocks + nextStreamkBlockIdx);
1020	                GemmCoord streamkActualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.streamkBlockCoord);
1021	                streamkBlockDec.streamkActualBlockShape = GemmCoord{
1022	                    streamkActualBlockShapeTmp.m(), streamkActualBlockShapeTmp.n(),
1023	                    ((kTileIdx + curKTileNum) % loopsMNK.k()) * tileMNK.k()};
1024	            }
1025	        }
1026	    }
1027	
1028	    CATLASS_DEVICE
1029	    uint32_t GetCoreIdx(uint32_t streamkBlockIdx)
1030	    {
1031	        if (streamkBlockIdx * loopsMNK.k() > kTileRemain * (kTileNumPerCore + 1)) {
1032	            return kTileRemain +
1033	                   (streamkBlockIdx * loopsMNK.k() - kTileRemain * (kTileNumPerCore + 1)) / kTileNumPerCore;
1034	        } else {
1035	            return streamkBlockIdx * loopsMNK.k() / (kTileNumPerCore + 1);
1036	        }
1037	    }
1038	
1039	    CATLASS_DEVICE
1040	    bool IsCross(uint32_t streamkBlockIdx)
1041	    {
1042	        // If the head part of the current block and the tail part of the previous block are computed by
1043	        // the same core, return true.
1044	        if (streamkBlockIdx * loopsMNK.k() > kTileRemain * (kTileNumPerCore + 1)) {
1045	            if ((streamkBlockIdx * loopsMNK.k() - kTileRemain * (kTileNumPerCore + 1)) % kTileNumPerCore == 0) {
1046	                return false;
1047	            } else {
1048	                return true;
1049	            }
1050	        } else {
1051	            if ((streamkBlockIdx * loopsMNK.k()) % (kTileNumPerCore + 1) == 0) {
1052	                return false;
1053	            } else {
1054	                return true;
1055	            }
1056	        }
1057	    }
1058	};
1059	
1060	struct DynamicStreamkGemmIdentityBlockSwizzle : public StreamkGemmIdentityBlockSwizzle<> {
1061	    uint32_t swizzleOffset{1};
1062	    uint32_t swizzleDirection{0};
1063	
1064	    CATLASS_DEVICE
1065	    DynamicStreamkGemmIdentityBlockSwizzle(
1066	        GemmCoord const& problemShape_, GemmCoord const& tileShape_, uint32_t coreNum_, uint32_t swizzleOffset_,
1067	        uint32_t swizzleDirection_)
1068	        : swizzleOffset(swizzleOffset_),
1069	          swizzleDirection(swizzleDirection_),
1070	          StreamkGemmIdentityBlockSwizzle<>(problemShape_, tileShape_, coreNum_)
1071	    {}
1072	
1073	    CATLASS_DEVICE
1074	    DynamicStreamkGemmIdentityBlockSwizzle(
1075	        GemmCoord const& problemShape_, GemmCoord const& tileShape_, uint32_t coreNum_)
1076	        : StreamkGemmIdentityBlockSwizzle<>(problemShape_, tileShape_, coreNum_)
1077	    {}
1078	
1079	    CATLASS_DEVICE
1080	    DynamicStreamkGemmIdentityBlockSwizzle()
1081	    {}
1082	
1083	    CATLASS_DEVICE
1084	    void SetSwizzleParams(uint32_t swizzleOffset_, uint32_t swizzleDirection_)
1085	    {
1086	        swizzleOffset = swizzleOffset_;
1087	        swizzleDirection = swizzleDirection_;
1088	    }
1089	
1090	    CATLASS_DEVICE
1091	    void GetStreamkBlockDec(uint32_t loopIdx, StreamkBlockDec& streamkBlockDec)
1092	    {
1093	        if (loopIdx < normalBlocks) {
1094	            streamkBlockDec.isStreamkBlock = false;
1095	            streamkBlockDec.isCrossBlock = false;
1096	            streamkBlockDec.blockCoord = GetBlockCoord(loopIdx);
1097	            streamkBlockDec.actualBlockShape = GetActualBlockShape(streamkBlockDec.blockCoord);
1098	        } else {
1099	            streamkBlockDec.isStreamkBlock = true;
1100	            uint32_t curKTileNum = kTileNumPerCore;
1101	            uint32_t kTileIdx = ((loopIdx - normalBlocks) * kTileNumPerCore + kTileRemain);
1102	            if (loopIdx - normalBlocks < kTileRemain) {
1103	                curKTileNum += 1;
1104	                kTileIdx = ((loopIdx - normalBlocks) * curKTileNum);
1105	            }
1106	            uint32_t streamkBlockIdx = kTileIdx / loopsMNK.k();
1107	            GemmCoord blockCoordTmp = GetBlockCoord(normalBlocks + streamkBlockIdx);
1108	            streamkBlockDec.blockCoord = GemmCoord{blockCoordTmp.m(), blockCoordTmp.n(), kTileIdx % loopsMNK.k()};
1109	
1110	            uint32_t nextStreamkBlockIdx = (kTileIdx + curKTileNum) / loopsMNK.k();
1111	            streamkBlockDec.isCrossBlock = false;
1112	            GemmCoord actualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.blockCoord);
1113	            if ((kTileIdx % loopsMNK.k() + curKTileNum) * tileMNK.k() > problemShape.k()) {
1114	                streamkBlockDec.actualBlockShape = GemmCoord{
1115	                    actualBlockShapeTmp.m(), actualBlockShapeTmp.n(),
1116	                    problemShape.k() - (kTileIdx % loopsMNK.k()) * tileMNK.k()};
1117	            } else {
1118	                streamkBlockDec.actualBlockShape =
1119	                    GemmCoord{actualBlockShapeTmp.m(), actualBlockShapeTmp.n(), curKTileNum * tileMNK.k()};
1120	            }
1121	            if (kTileIdx % loopsMNK.k() + curKTileNum > loopsMNK.k()) {
1122	                streamkBlockDec.isCrossBlock = true;
1123	                streamkBlockDec.streamkBlockCoord = GetBlockCoord(normalBlocks + nextStreamkBlockIdx);
1124	                GemmCoord streamkActualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.streamkBlockCoord);
1125	                streamkBlockDec.streamkActualBlockShape = GemmCoord{
1126	                    streamkActualBlockShapeTmp.m(), streamkActualBlockShapeTmp.n(),
1127	                    ((kTileIdx + curKTileNum) % loopsMNK.k()) * tileMNK.k()};
1128	            }
1129	        }
1130	    }
1131	
1132	    CATLASS_DEVICE
1133	    GemmCoord GetBlockCoord(uint32_t taskIdx)
1134	    {
1135	        uint32_t innerIdx = taskIdx % GetCoreLoops();
1136	        if (swizzleDirection == 0) { // Zn
1137	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), swizzleOffset);
1138	            uint32_t tileBlockIdx = innerIdx / (swizzleOffset * loopsMNK.n());
1139	            uint32_t inTileBlockIdx = innerIdx % (swizzleOffset * loopsMNK.n());
1140	
1141	            uint32_t nRow = swizzleOffset;
1142	            if (tileBlockIdx == tileBlockLoop - 1) {
1143	                nRow = loopsMNK.m() - swizzleOffset * tileBlockIdx;
1144	            }
1145	            uint32_t mIdx = tileBlockIdx * swizzleOffset + inTileBlockIdx % nRow;
1146	            uint32_t nIdx = inTileBlockIdx / nRow;
1147	            if (tileBlockIdx % 2 == 1) {
1148	                nIdx = loopsMNK.n() - nIdx - 1;
1149	            }
1150	            return GemmCoord{mIdx, nIdx, 0};
1151	        } else { // Nz
1152	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), swizzleOffset);
1153	            uint32_t tileBlockIdx = innerIdx / (swizzleOffset * loopsMNK.m());
1154	            uint32_t inTileBlockIdx = innerIdx % (swizzleOffset * loopsMNK.m());
1155	
1156	            uint32_t nCol = swizzleOffset;
1157	            if (tileBlockIdx == tileBlockLoop - 1) {
1158	                nCol = loopsMNK.n() - swizzleOffset * tileBlockIdx;
1159	            }
1160	            uint32_t mIdx = inTileBlockIdx / nCol;
1161	            uint32_t nIdx = tileBlockIdx * swizzleOffset + inTileBlockIdx % nCol;
1162	            if (tileBlockIdx % 2 == 1) {
1163	                mIdx = loopsMNK.m() - mIdx - 1;
1164	            }
1165	            return GemmCoord{mIdx, nIdx, 0};
1166	        }
1167	    }
1168	};
1169	
1170	/**
1171	 * ColumnBlockSwizzle:  split column
1172	 */
1173	struct ColumnBlockSwizzle : public GemmIdentityBlockSwizzle<> {
1174	    uint32_t nBlocks;
1175	    uint32_t mBlocks;
1176	    uint32_t blocksPerCore;
1177	    uint32_t remainder;
1178	    uint32_t coreIdx;
1179	    uint32_t coreNum;
1180	    uint32_t perCoreTailColumns;
1181	    uint32_t tailTaskStartIdx;
1182	
1183	    CATLASS_DEVICE
1184	    ColumnBlockSwizzle()
1185	    {}
1186	
1187	    CATLASS_DEVICE
1188	    ColumnBlockSwizzle(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
1189	        : GemmIdentityBlockSwizzle<>(problemShape_, tileMN_)
1190	    {
1191	        coreNum = AscendC::GetBlockNum();
1192	        coreIdx = AscendC::GetBlockIdx();
1193	        if (AscendC::GetSubBlockNum() != 1) {
1194	            coreIdx /= 2;
1195	        }
1196	
1197	        SplitTask();
1198	    }
1199	
1200	    CATLASS_DEVICE
1201	    void Update(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
1202	    {
1203	        problemShape = problemShape_;
1204	        tileMN = tileMN_;
1205	
1206	        loopsMN = CeilDiv(MatrixCoord(problemShape.GetCoordMN()), tileMN);
1207	        SplitTask();
1208	    }
1209	
1210	    CATLASS_DEVICE
1211	    void SplitTask()
1212	    {
1213	        nBlocks = loopsMN.column();
1214	        mBlocks = loopsMN.row();
1215	        // 每个核处理平均处理的列block数
1216	        blocksPerCore = problemShape.n() / (coreNum * tileMN.column());
1217	        uint32_t tailColumn = problemShape.n() % (coreNum * tileMN.column());
1218	
1219	        perCoreTailColumns = tailColumn / coreNum;
1220	
1221	        remainder = tailColumn % coreNum;
1222	
1223	        tailTaskStartIdx = blocksPerCore * mBlocks;
1224	    }
1225	
1226	    CATLASS_DEVICE
1227	    uint32_t GetCoreLoops() const
1228	    {
1229	        uint32_t blockPerRowBlock = blocksPerCore;
1230	        if (perCoreTailColumns > 0 || remainder > coreIdx) {
1231	            blockPerRowBlock += 1;
1232	        }
1233	        return mBlocks * blockPerRowBlock;
1234	    }
1235	
1236	    CATLASS_DEVICE
1237	    uint32_t GetIsTail(uint32_t taskIdx) const
1238	    {
1239	        return (taskIdx >= tailTaskStartIdx);
1240	    }
1241	
1242	    CATLASS_DEVICE
1243	    uint32_t GetTailOffset() const
1244	    {
1245	        uint32_t tailOffset = coreIdx * perCoreTailColumns;
1246	        tailOffset += (remainder > coreIdx ? coreIdx : remainder);
1247	        return tailOffset;
1248	    }
1249	
1250	    CATLASS_DEVICE
1251	    GemmCoord GetBlockCoord(uint32_t taskIdx)
1252	    {
1253	        uint32_t mIdx = taskIdx % mBlocks;
1254	        uint32_t columnLocalIdx = taskIdx / mBlocks;
1255	
1256	        uint32_t nIdx;
1257	        if (taskIdx < tailTaskStartIdx) {
1258	            nIdx = blocksPerCore * coreIdx + columnLocalIdx;
1259	        } else {
1260	            nIdx = blocksPerCore * coreNum;
1261	        }
1262	
1263	        return GemmCoord{mIdx, nIdx, 0};
1264	    }
1265	
1266	    /**
1267	     * GetActualBlockShape: 根据 blockCoord 计算实际块形状（重写基类方法）
1268	     */
1269	    CATLASS_DEVICE
1270	    GemmCoord GetActualBlockShape(GemmCoord blockCoord)
1271	    {
1272	        if (blockCoord.n() >= loopsMN.column()) {
1273	            return GemmCoord{0, 0, problemShape.k()};
1274	        }
1275	
1276	        uint32_t mActual =
1277	            (blockCoord.m() == (loopsMN.row() - 1)) ? (problemShape.m() - blockCoord.m() * tileMN.row()) : tileMN.row();
1278	        uint32_t kActual = problemShape.k();
1279	
1280	        uint32_t nActual;
1281	        if (blockCoord.n() < blocksPerCore * coreNum) {
1282	            nActual = tileMN.column();
1283	        } else if (remainder > coreIdx) {
1284	            nActual = perCoreTailColumns + 1;
1285	        } else {
1286	            nActual = perCoreTailColumns;
1287	        }
1288	
1289	        return GemmCoord{mActual, nActual, kActual};
1290	    }
1291	};
1292	
1293	} // namespace Catlass::Gemm::Block
1294	
1295	#endif // CATLASS_GEMM_BLOCK_BLOCK_SWIZZLE_HPP
